        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_agentry_ffi_checksum_method_leafcancellation_close() != 11762) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_agentry_ffi_checksum_constructor_coreruntime_new() != 14410) {
